{"probes": [{"obligation_id": "OB-007", "strategy": "example", "rationale": "Directly falsifies the clause if UnsatisfiableRange were implemented as (or inheriting from) ValueError, since the spec says it must NOT be a subclass of ValueError, while still requiring it to be a normal Exception subclass.", "code": "import impl


def test_unsatisfiable_range_is_not_a_valueerror_subclass():
    assert not issubclass(impl.UnsatisfiableRange, ValueError), (
        "UnsatisfiableRange must not be a subclass of ValueError, but issubclass() "
        "returned True"
    )
    assert issubclass(impl.UnsatisfiableRange, Exception), (
        "UnsatisfiableRange must still be a subclass of Exception"
    )
"}]}
